@Component("feature-entity-projector")
public class FeatureEntityProjector implements EntityProjector<Feature>{
		
	// core constructor
	public FeatureEntityProjector(ProjectorRegistry registry,
										FeatureRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Feature> getEntityClass() {
		return Feature.class;
	}

    /*
	 * Insert a Feature
	 * 
     * @param	entity Feature
     */
    public Feature create( Feature entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Feature
	 * 
     * @param	entity Feature
     */
    public Feature update( Feature entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Feature
	 * 
     * @param	id		UUID
     */
    public Feature delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Feature entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a FeatureSet
     * 
     * @param	parentId	UUID
     * @param	assignment 	FeatureSet 
     * @return	Feature
     */
    public Feature assignFeatureSet( UUID parentId, FeatureSet assignment ) {
	    LOGGER.info("assigning FeatureSet as " + assignment.toString() );

	    Feature parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( FeatureSet.class, assignment.getFeatureSetId());

	    // ------------------------------------------
		// assign the FeatureSet to the parent entity
		// ------------------------------------------ 
	    parentEntity.setFeatureSet( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the FeatureSet
	 * 
	 * @param	parentId		UUID
	 * @return	Feature
	 */
	public Feature unAssignFeatureSet( UUID parentId ) {
		Feature parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning FeatureSet on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the FeatureSet on the parent entithy
		// ------------------------------------------     
	    parentEntity.setFeatureSet(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the SourceDatasets
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Feature
     */
    public Feature addToSourceDatasets( UUID parentId, DataSet addTo ) {
	    LOGGER.info("handling AssignSourceDatasetsToFeatureEvent - " );
	    
	    Feature parentEntity = repository.findById(parentId).get();
	    DataSet child = registry.project( DataSet.class, addTo.getDataSetId());
	    
	    parentEntity.getSourceDatasets().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the SourceDatasets
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Feature
     */
	public Feature removeFromSourceDatasets( UUID parentId, DataSet removeFrom ) {
	    LOGGER.info("handling RemoveSourceDatasetsFromFeatureEvent " );
	
	    Feature parentEntity = repository.findById(parentId).get();
	    DataSet child = registry.project( DataSet.class, removeFrom.getDataSetId());
	    
	    parentEntity.getSourceDatasets().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

    /*
     * Add to the Models
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Feature
     */
    public Feature addToModels( UUID parentId, Model addTo ) {
	    LOGGER.info("handling AssignModelsToFeatureEvent - " );
	    
	    Feature parentEntity = repository.findById(parentId).get();
	    Model child = registry.project( Model.class, addTo.getModelId());
	    
	    parentEntity.getModels().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Models
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Feature
     */
	public Feature removeFromModels( UUID parentId, Model removeFrom ) {
	    LOGGER.info("handling RemoveModelsFromFeatureEvent " );
	
	    Feature parentEntity = repository.findById(parentId).get();
	    Model child = registry.project( Model.class, removeFrom.getModelId());
	    
	    parentEntity.getModels().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

    /*
     * Add to the TrainingRuns
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Feature
     */
    public Feature addToTrainingRuns( UUID parentId, TrainingRun addTo ) {
	    LOGGER.info("handling AssignTrainingRunsToFeatureEvent - " );
	    
	    Feature parentEntity = repository.findById(parentId).get();
	    TrainingRun child = registry.project( TrainingRun.class, addTo.getTrainingRunId());
	    
	    parentEntity.getTrainingRuns().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the TrainingRuns
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Feature
     */
	public Feature removeFromTrainingRuns( UUID parentId, TrainingRun removeFrom ) {
	    LOGGER.info("handling RemoveTrainingRunsFromFeatureEvent " );
	
	    Feature parentEntity = repository.findById(parentId).get();
	    TrainingRun child = registry.project( TrainingRun.class, removeFrom.getTrainingRunId());
	    
	    parentEntity.getTrainingRuns().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Feature via an FindFeatureQuery
     * @return 	query	FindFeatureQuery
     */
    @SuppressWarnings("unused")
    public Feature find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Feature - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Features
     *
     * @param	query	FindAllFeatureQuery 
     * @return 	List<Feature> 
     */
    @SuppressWarnings("unused")
    public List<Feature> findAll( FindAllFeatureQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Feature - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final FeatureRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(FeatureEntityProjector.class.getName());

}
